function updateTimer(){if(!$('#clock'))return;const n=timerEnd?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):1500;$('#clock').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(timerEnd&&n===0){api.send('pet-event','timer-finish');status('Focus timer finished.');timerEnd=0;}}

